"""Design test: richer need page (used for 'control' only, when V2=1)."""
import os
CSS = '<style>\n.v2{--ink2:#fff}\n.page.v2 .wrap>*{max-width:none}.page.v2 .wrap>.txt{max-width:66ch}.page.v2 .hero .pill{color:#fff;text-transform:none;letter-spacing:0}\n.v2 .txt{max-width:66ch}\n.v2 .prog{position:fixed;top:0;left:0;height:4px;width:0;background:var(--a);z-index:50}\n/* hero */\n.v2 .hero{position:relative;background:linear-gradient(135deg,var(--d) 0%,var(--a) 100%);color:#fff;overflow:hidden;padding:56px 0 120px}\n.v2 .hero::before{content:"";position:absolute;right:-120px;top:-140px;width:520px;height:520px;border-radius:50%;background:rgba(255,255,255,.07)}\n.v2 .hero::after{content:"";position:absolute;left:-90px;bottom:-160px;width:380px;height:380px;border-radius:50%;background:rgba(255,255,255,.06)}\n.v2 .hero .wrap{position:relative;z-index:1;display:grid;grid-template-columns:1.1fr 1fr;gap:30px 50px;align-items:center}\n.v2 .hero .crumb{color:#fff;opacity:.85}\n.v2 .hero .tag{color:#F2D79A;letter-spacing:.14em}\n.v2 .hero h1{font-size:clamp(3.6rem,9vw,6.6rem);line-height:.95;margin:6px 0 14px;color:#fff;letter-spacing:-.01em}\n.v2 .hero .lede{font-size:1.4rem;color:#fff;opacity:.95;max-width:26ch;line-height:1.3}\n.v2 .hero .pills{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}\n.v2 .pill{display:inline-flex;align-items:center;gap:8px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.35);border-radius:999px;padding:8px 16px;font-weight:600;font-size:.95rem;backdrop-filter:blur(4px)}\n.v2 .pill i{display:inline-flex;gap:3px}.v2 .pill i b{width:14px;height:8px;border-radius:4px;background:rgba(255,255,255,.35)}.v2 .pill i b.on{background:#F2D79A}\n.v2 .hero .art{background:rgba(255,255,255,.14);border-radius:36px;padding:14px;box-shadow:0 30px 60px rgba(0,0,0,.25);transform:rotate(1.5deg)}\n.v2 .hero .art svg{width:100%;height:auto;display:block;border-radius:26px}\n.v2 .wave{position:absolute;left:0;right:0;bottom:-1px;width:100%;height:80px;display:block;z-index:2}\n/* answer */\n.v2 .answer{background:var(--bg,#F6EFE0);padding:6px 0 10px}\n.v2 .quote{position:relative;margin:-60px auto 0;background:var(--card);border-radius:26px;box-shadow:0 24px 60px rgba(46,42,34,.16);padding:34px 40px 34px 90px;display:grid;grid-template-columns:1fr auto;gap:24px;align-items:center;z-index:3}\n.v2 .quote::before{content:"“";position:absolute;left:24px;top:-6px;font-family:var(--serif);font-size:8rem;line-height:1;color:var(--a);opacity:.9}\n.v2 .quote .k{font-size:.78rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--a);margin:0 0 6px}\n.v2 .quote p.big{font-family:var(--serif);font-size:clamp(1.7rem,3.2vw,2.5rem);line-height:1.15;margin:0;font-weight:600}\n.v2 .gauge{text-align:center;min-width:150px}.v2 .gauge svg{width:150px;height:auto;display:block}.v2 .gauge b{display:block;margin-top:-4px}.v2 .gauge span{font-size:.85rem;color:var(--soft)}\n.v2 .today{margin-top:22px;display:flex;align-items:center;gap:18px;background:var(--a);color:#fff;border-radius:20px;padding:20px 26px}\n.v2 .today .ic{flex:none;width:52px;height:52px;border-radius:50%;background:rgba(255,255,255,.2);display:grid;place-items:center}\n.v2 .today .ic svg{width:28px;height:28px}\n.v2 .today .k{font-size:.78rem;letter-spacing:.12em;text-transform:uppercase;font-weight:700;color:#F2D79A;margin:0}\n.v2 .today p.go{margin:2px 0 0;font-size:1.25rem;font-weight:600;line-height:1.3}\n/* sections */\n.v2 .blk{padding:64px 0}\n.v2 .blk.tint{background:var(--t)}\n.v2 .blk.dark{background:var(--d);color:#fff}\n.v2 .blk.dark h2,.v2 .blk.dark .sh small{color:#fff}\n.v2 .sh{position:relative;margin:0 0 22px;padding-top:34px}\n.v2 .sh .n{position:absolute;right:0;top:-6px;font-family:var(--serif);font-size:7rem;font-weight:700;line-height:1;color:var(--a);opacity:.13;pointer-events:none}\n.v2 .blk.dark .sh .n{color:#fff;opacity:.12}\n.v2 .sh h2{position:relative;font-size:clamp(2.1rem,4.4vw,3.1rem);margin:0;line-height:1.05}\n.v2 .sh small{position:relative;display:block;margin-top:6px;font-size:1.05rem;color:var(--soft)}\n.v2 .vid2{display:grid;grid-template-columns:1.25fr 1fr;gap:22px;align-items:stretch}\n.v2 .vid2 .vidbox,.v2 .vid2 .glance{margin:0;border-radius:22px;border-top-width:6px;box-shadow:0 14px 34px rgba(46,42,34,.10)}\n.v2 .pull{font-family:var(--serif);font-size:clamp(1.8rem,3.4vw,2.6rem);line-height:1.2;color:var(--d);margin:0 0 20px;max-width:24ch}\n.v2 .pull em{font-style:normal;background:linear-gradient(transparent 62%,rgba(242,215,154,.9) 62%)}\n.v2 .rings{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin:6px 0 26px}\n.v2 .ring{display:flex;gap:18px;align-items:center;background:var(--card);border-radius:22px;padding:20px 22px;box-shadow:0 10px 28px rgba(46,42,34,.08);border:1px solid var(--line)}\n.v2 .ring svg{flex:none;width:92px;height:92px}.v2 .ring b{display:block;font-family:var(--serif);font-size:2.3rem;line-height:1;color:var(--d)}.v2 .ring span{display:block;margin-top:4px;font-size:.98rem}\n.v2 .limits{border-radius:18px;border-left-width:8px;margin:26px 0 0}\n.v2 .acts{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}\n.v2 .act{position:relative;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.25);border-radius:22px;padding:26px 26px 24px;overflow:hidden}\n.v2 .act::after{content:attr(data-n);position:absolute;right:14px;top:-14px;font-family:var(--serif);font-size:7rem;font-weight:700;color:#fff;opacity:.1;line-height:1}\n.v2 .act .ic{width:48px;height:48px;border-radius:14px;background:#F2D79A;color:var(--d);display:grid;place-items:center;margin-bottom:12px}.v2 .act .ic svg{width:26px;height:26px}\n.v2 .act p{margin:0;font-size:1.15rem;line-height:1.4}\n.v2 .note2{margin-top:16px;opacity:.8;font-size:.95rem}\n.v2 .lives{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}\n.v2 .life{background:var(--card);border-radius:22px;overflow:hidden;box-shadow:0 12px 30px rgba(46,42,34,.10);border:1px solid var(--line);transition:transform .25s}\n.v2 .life:hover{transform:translateY(-6px)}\n.v2 .life .top{background:linear-gradient(135deg,var(--a),var(--d));color:#fff;padding:20px 22px;display:flex;align-items:center;gap:14px}\n.v2 .life .av{width:54px;height:54px;border-radius:50%;background:rgba(255,255,255,.22);display:grid;place-items:center;font-family:var(--serif);font-weight:700;font-size:1.7rem}\n.v2 .life .top b{font-family:var(--serif);font-size:1.5rem;line-height:1.1}.v2 .life .top span{display:block;font-size:.9rem;opacity:.85}\n.v2 .life p{margin:0;padding:18px 22px 22px;font-size:1rem;line-height:1.5}\n.v2 .mapcard{background:var(--card);border-radius:24px;padding:20px;border:1px solid var(--line);box-shadow:0 12px 30px rgba(46,42,34,.08)}\n.v2 .cl{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin:18px 0}\n.v2 .cl li{margin:0;border-radius:16px;border-left:6px solid var(--a)}\n.v2 .src{padding:10px 0 20px}\n/* motion */\n.v2 .rv{opacity:0;transform:translateY(22px);transition:opacity .7s ease,transform .7s ease}\n.v2 .rv.in{opacity:1;transform:none}\n@media (prefers-reduced-motion:reduce){.v2 .rv{opacity:1;transform:none;transition:none}}\n@media (max-width:860px){.v2 .hero .wrap,.v2 .vid2,.v2 .rings,.v2 .acts,.v2 .lives,.v2 .cl{grid-template-columns:1fr}.v2 .quote{grid-template-columns:1fr;padding:30px 24px 24px;margin-top:-50px}.v2 .quote::before{position:static;display:block;height:56px;margin-bottom:-14px;font-size:6rem}.v2 .hero{padding:36px 0 100px}.v2 .hero .art{transform:none;max-width:340px}.v2 .sh .n{font-size:5rem}}\n</style>'

def build(ns):
    header, footer, scene, ACC, tint, dark, diagram, CAPT, conn_svg, FEEL, NEEDS, EX = (ns[k] for k in ("header","footer","scene","ACC","tint","dark","diagram","CAPT","conn_svg","FEEL","NEEDS","EX"))
    ns_ = ns
    BUILT_NEED = ns.get("BUILT_NEED", [])
    def page(slug, d, OUT):
        ex = dict(EX[slug]); _fl = [f for f in FEEL if slug in [x[0] for x in FEEL[f]["stops"]]]
        ex["conn"] = [c for c in ex["conn"] if c[1] == "need"] + [(f, "feel", "", "") for f in _fl]
        a = ACC[slug]
        says = d["says"]
        vid = ns['vidbox'](slug, d["name"])
        vign = "".join(f'<div class="life"><div class="av">{n[0]}</div><b>{n}</b><p>{t}</p></div>' for n, t in ex["ex"])
        steps = "".join(f'<li><div>{t}</div></li>' for t in d["tryit"])
        def cl(t, kind, ev, txt):
            if kind == "need": return f'<li><a href="../need/{t}.html"><b>{NEEDS[t]["name"]}</b></a><span class="k">{"Seen in studies" if ev=="study" else ("Thin evidence" if ev=="thin" else ("Same framework" if ev=="frame" else "Not yet researched"))}</span><br>{txt}</li>'
            return f'<li><a href="../feel/{t}.html"><b>Feeling: {FEEL[t]["name"]}</b></a><br>This need may sit behind this feeling.</li>'
        cll = "".join(cl(*c) for c in ex["conn"])
        ring = lambda pct: '<svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="46" fill="var(--a)"/><g fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"><path d="M30 62 L44 46 L54 56 L72 34"/><path d="M60 34 H72 V46"/></g></svg>'
        icons = ['<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>','<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M16 8l-2 6-6 2 2-6z"/></svg>']
        acts = "".join(f'<div class="act rv" data-n="{i+1}"><div class="ic">{icons[i%2]}</div><p>{t}</p></div>' for i, t in enumerate(d["tryit"]))
        lives = "".join(f'<div class="life rv"><div class="top"><div class="av">{n[0]}</div><div><b>{n.split(",")[0]}</b><span>{n.split(",")[1].strip() + " years" if "," in n else ""}</span></div></div><p>{t}</p></div>' for n, t in ex["ex"])
        wave = '<svg class="wave" viewBox="0 0 1440 80" preserveAspectRatio="none" aria-hidden="true"><path d="M0 40 C 240 90 480 0 720 36 C 960 72 1200 10 1440 44 L1440 80 L0 80 Z" fill="#F6EFE0"/></svg>'
        gauge = '<div class="gauge"><svg viewBox="0 0 120 70" aria-hidden="true"><path d="M10 62 A50 50 0 0 1 110 62" fill="none" stroke="var(--t)" stroke-width="14" stroke-linecap="round"/><path d="M10 62 A50 50 0 0 1 85 18.7" fill="none" stroke="var(--a)" stroke-width="14" stroke-linecap="round"/></svg><b>Some evidence</b><span>A link, cause not shown</span></div>'
        return header("../", "") + f"""
<main class="page np v2" style="--a:{a};--t:{tint(a)};--d:{dark(a,.5)}"><div class="prog" id="prog"></div>
<section class="hero"><div class="wrap">
<div><a class="crumb" href="../index.html#needs">← All needs</a><p class="tag">MIND NEED</p><h1>{d["name"]}</h1><p class="lede">{d["lede"]}</p>
<div class="pills"><span class="pill"><i><b class="on"></b><b class="on"></b><b></b></i>Some evidence</span><span class="pill">Video · 1 min</span><span class="pill">5 min read</span></div></div>
<div class="art">{scene(slug)}</div></div>{wave}</section>
<section class="answer"><div class="wrap">
<div class="quote rv"><div><p class="k">The short answer</p><p class="big">Feeling that you decide, even about small things, goes with better mood.</p></div>{gauge}</div>
<div class="today rv"><div class="ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></div><div><p class="k">Try this today</p><p class="go">Look for one small choice that is yours, and make it on purpose.</p></div></div>
</div></section>
<section class="blk"><div class="wrap"><div class="sh"><span class="n">1</span><h2>See it in a minute</h2><small>Watch, or look at the picture.</small></div>
<div class="vid2 rv">{vid}<figure class="glance"><figcaption><b>At a glance</b></figcaption>{diagram(slug)}<p class="cap">{CAPT[slug]}</p></figure></div></div></section>
<section class="blk tint"><div class="wrap"><div class="sh"><span class="n">2</span><h2>In plain words</h2></div>
<p class="pull rv">You are the one who <em>decides</em>, at least about some things.</p><p class="txt rv">{ex["plain"]}</p><p class="vnote txt">A simple way to picture it. The research below says how sure we are.</p></div></section>
<section class="blk"><div class="wrap"><div class="sh"><span class="n">3</span><h2>What research says</h2><small>Links across many studies. Most cannot show what causes what.</small></div>
<div class="rings rv"><div class="ring">{ring(62)}<div><b>16 studies</b><span>A stronger sense of control went with better mood. The link was moderate.</span></div></div><div class="ring">{ring(80)}<div><b>881 groups</b><span>People supported to choose feel more free, and report better mood.</span></div></div></div>
{"".join(f'<p class="txt rv">{p}</p>' for p in says)}
<div class="limits rv"><b>How far to trust it</b>{d["limits"]}</div></div></section>
<section class="blk dark"><div class="wrap"><div class="sh"><span class="n">4</span><h2>What you can try</h2><small>Small steps. Ideas, not tested treatments.</small></div>
<div class="acts">{acts}</div></div></section>
<section class="blk"><div class="wrap"><div class="sh"><span class="n">5</span><h2>In everyday life</h2><small>Made-up examples to help you see yourself. They are not study results.</small></div>
<div class="lives">{lives}</div></div></section>
<section class="blk tint"><div class="wrap"><div class="sh"><span class="n">6</span><h2>How it connects</h2></div>
<div class="mapcard rv">{conn_svg(slug, ex["conn"])}</div><p class="legend txt">Dashed line: a link seen in studies that only observe. Dash-dot line: thin evidence, or ideas that belong to the same framework. Dotted line: noted on the map, not yet researched here. Gold: feelings.</p><ul class="cl">{cll}</ul><p class="txt">{d["also"]}</p></div></section>
<section class="blk src"><div class="wrap"><div class="sources" style="margin-top:0"><b>Sources</b><ul>{"".join(f"<li>{s}</li>" for s in d["sources"])}</ul></div></div></section>
<script>(function(){{var p=document.getElementById('prog');function u(){{var h=document.documentElement;p.style.width=(h.scrollTop/(h.scrollHeight-h.clientHeight)*100)+'%'}}addEventListener('scroll',u,{{passive:true}});u();
var els=document.querySelectorAll('.rv');if(!('IntersectionObserver' in window)){{els.forEach(function(e){{e.classList.add('in')}});return}}
var io=new IntersectionObserver(function(es){{es.forEach(function(e){{if(e.isIntersecting){{e.target.classList.add('in');io.unobserve(e.target)}}}})}},{{threshold:.12}});els.forEach(function(e){{io.observe(e)}});}})();</script>
</main>""" + footer("../")
    return page
